/* @lc app=leetcode id=3213 lang=kotlin */
class Solution { fun minimumCost(target: String, words: Array<String>, costs: IntArray): Int = words.indices.fold(mutableMapOf<String, Int>()) { map, i -> map.also { it[words[i]] = minOf(it.getOrDefault(words[i], Int.MAX_VALUE), costs[i]) } }.let { map -> map.keys.groupBy { it.length }.let { byLen -> IntArray(target.length + 1) { 1_000_000_000 }.apply { this[target.length] = 0 }.also { dp -> (target.length - 1 downTo 0).forEach { i -> byLen.keys.forEach { len -> if (i + len <= target.length && dp[i + len] < 1_000_000_000) map[target.substring(i, i + len)]?.let { dp[i] = minOf(dp[i], it + dp[i + len]) } } } }[0].let { if (it >= 1_000_000_000) -1 else it } } } }